/* From Uiverse.io by Manish-Tamang  - Tags: button, hover effect, html, css, 3d button, button hover effect  */
.__UIV_SCOPE__ a {
  position: relative;
  display: inline-flex;
  width: 180px;
  height: 55px;
  margin: 0 15px;
  perspective: 1000px;
  text-decoration: none;
}

.__UIV_SCOPE__ a:before,
.__UIV_SCOPE__ a:after {
  position: absolute;
  content: "3D HOVER";
  height: 55px;
  width: 180px;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 5px solid black;
  box-sizing: border-box;
  font-size: 19px;
  letter-spacing: 1px;
  font-family: "Montserrat", sans-serif;
  text-align: center;
  transition: transform 0.25s;
}

.__UIV_SCOPE__ a:before {
  color: #fff;
  background: #000;
  transform: rotateY(0deg) translateZ(25px);
}

.__UIV_SCOPE__ a:after {
  color: #000;
  transform: rotateX(90deg) translateZ(25px);
}

.__UIV_SCOPE__ a:hover:before {
  transform: translateZ(-25px) rotateX(-90deg);
}

.__UIV_SCOPE__ a:hover:after {
  transform: rotateY(0deg) translateZ(25px);
}
